package hu.synostream.android;
import org.json.*;import org.junit.*;import java.util.*;import static org.junit.Assert.*;
public class LocalEditsTest {
    private Library.Card show(String path,String title,long id){Library.Card c=new Library.Card(path,title,false);c.id=id;c.episodeRoots.add(path);return c;}
    @Test public void mergeUsesTargetNameAndAllRoots() throws Exception {Library.Card a=show("/show/a","Wrong",1),b=show("/show/b","Target",2);LocalEdits edits=new LocalEdits("{}");edits.merge("lib",a,b);List<Library.Card> result=edits.apply(List.of(a,b),"lib");assertEquals(1,result.size());assertEquals("Target",result.get(0).title);assertEquals(2,result.get(0).id);assertEquals(Set.of("/show/a","/show/b"),new HashSet<>(result.get(0).episodeRoots));assertFalse(result.get(0).manualGroupId.isEmpty());assertEquals(List.of("/show/b"),b.episodeRoots);}
    @Test public void mergeSurvivesRestartAndCanBeUndone() throws Exception {Library.Card a=show("/a","A",1),b=show("/b","B",2);LocalEdits edits=new LocalEdits("{}");edits.merge("lib",a,b);edits=new LocalEdits(edits.toString());List<Library.Card> merged=edits.apply(List.of(a,b),"lib");edits.unmerge(merged.get(0).manualGroupId);assertEquals(2,edits.apply(List.of(a,b),"lib").size());}
    @Test public void mergeIsScopedToItsLibrary() throws Exception {Library.Card a=show("/a","A",1),b=show("/b","B",2);LocalEdits edits=new LocalEdits("{}");edits.merge("one",a,b);assertEquals(2,edits.apply(List.of(a,b),"two").size());}
    @Test public void missingTargetCannotInventStaleCards() throws Exception {Library.Card a=show("/a","A",1),b=show("/b","B",2);LocalEdits edits=new LocalEdits("{}");edits.merge("lib",a,b);List<Library.Card> result=edits.apply(List.of(a),"lib");assertEquals(1,result.size());assertEquals("A",result.get(0).title);assertTrue(result.get(0).manualGroupId.isEmpty());}
    @Test public void hidingDoesNotAlterTheRawMediaInventory() throws Exception {Library.Card a=show("/a","A",1),b=show("/b","B",2);List<Library.Card> raw=new ArrayList<>(List.of(a,b));LocalEdits edits=new LocalEdits("{}");edits.hide(a);assertEquals(1,edits.apply(raw,"lib").size());assertEquals(2,raw.size());LocalEdits restarted=new LocalEdits(edits.toString());assertEquals(1,restarted.apply(raw,"lib").size());restarted.restore("tv:/a");assertEquals(2,restarted.apply(raw,"lib").size());}
    @Test public void pendingManualCorrectionWinsAndCanBecomeSynced() throws Exception {LocalEdits edits=new LocalEdits("{}");JSONObject info=new JSONObject().put("id",99).put("name","Jó magyar cím").put("overview","Leírás");Library.Card card=show("/show","Bad",1);edits.manual(false,"/show",info);assertEquals("Jó magyar cím",edits.apply(List.of(card),"lib").get(0).title);assertEquals(99,edits.overrides().get("tv:/show").getLong("id"));edits.synced(false,"/show");assertTrue(edits.overrides().isEmpty());}
    @Test public void extendingAnExistingGroupFlattensIt() throws Exception {Library.Card a=show("/a","A",1),b=show("/b","B",2),c=show("/c","C",3);LocalEdits edits=new LocalEdits("{}");edits.merge("lib",a,b);Library.Card group=edits.apply(List.of(a,b,c),"lib").stream().filter(x->!x.manualGroupId.isEmpty()).findFirst().get();edits.merge("lib",group,c);List<Library.Card> result=edits.apply(List.of(a,b,c),"lib");assertEquals(1,result.size());assertEquals("C",result.get(0).title);assertEquals(3,result.get(0).episodeRoots.size());}
}
